      EXECUTE IMMEDIATE 'CREATE VIEW IF NOT EXISTS ' || :tgt || '.V_BUILD_CONTEXT AS SELECT ''Cortex Agent Deployment'' AS SOLUTION,''' || :tgt || ''' AS BUILT_IN,''DISCOVER'' AS MODE,''DISCOVER'' AS TIER,14 AS WINDOW_DAYS,CURRENT_TIMESTAMP() AS BUILT_AT,FALSE AS ACTIONS_ENABLED,FALSE AS SAMPLE_ACTIONS_ENABLED,0 AS SCHEDULED_COMPONENTS,0 AS STANDING_CREDITS_PER_MONTH,0 AS VOLUME_COMPONENTS,''AGENT'' AS SETTING_PREFIX';
      EXECUTE IMMEDIATE 'CREATE STAGE IF NOT EXISTS ' || :tgt || '.APP_STAGE';
      EXECUTE IMMEDIATE 'SHOW STREAMLITS IN SCHEMA ' || :tgt;
